possible comparisons

for(i in 1:6)
           {
DEtable <- topTable(fit2,coef = i,number =
numberDE,adjust = "fdr",sort.by = "P");
    DEList[i] <- list(DEtable);
            AllDEGenes <-
c(AllDEGenes,as.character(DEList[[i]][,"ID"]));
            AllDE_FDR <-
c(AllDE_FDR,as.character(DEList[[i]][,"P.Value"]));
           }


